\section{Introduction}

Euler's totient $\varphi(n)$ counts integers in $\{1,\dots,n\}$ coprime to $n$. It
is multiplicative, highly irregular under additive shifts, and central to number
theory. The \emph{unit-shift equation}
\begin{equation}\label{eq:shift}
  \varphi(n) = \varphi(n+1)
\end{equation}
asks for consecutive integers with equal totient. Since $n$ and $n+1$ are coprime
with typically unrelated factorizations, solutions of \eqref{eq:shift} are
coincidental, yet occur often empirically and are believed (unproven) to be
infinite.

The quantitative study of \eqref{eq:shift} was settled, up to the secondary
exponent term, by Graham, Holt, and Pomerance (GHP):
\begin{equation}\label{eq:upper}
  \Sphi(x) \;\ll\; x\,\exp\!\Big\{-\big(\tfrac12 - o(1)\big)\sqrt{\log x\,\log_2 x}\Big\},
\end{equation}
where $\log_2 x = \log\log x$, together with the matching tightness lower bound
\begin{equation}\label{eq:lower}
  \Sphi(x) \;\ge\; C\,x\,\exp\!\Big\{-\big(\tfrac12 + o(1)\big)\sqrt{\log x\,\log_2 x}\Big\}.
\end{equation}
The exponent $\sqrt{\log x\,\log_2 x}$ is the signature of smooth-number balancing.

This paper does not formalize \eqref{eq:lower} analytically; it formalizes the
\emph{constructive skeleton} on which \eqref{eq:lower} rests: the lower bound is a
counting statement over an explicitly constructed family of solutions of
\eqref{eq:shift}. We machine-verify the primitives any such argument consumes:
witness certification by multiplicativity (Section~\ref{sec:witnesses}), a counting
transfer theorem (Section~\ref{sec:count}), and structural constraints
(Section~\ref{sec:struct}).

\section{Preliminaries on the totient}

We use three classical evaluation principles (library names
\texttt{Nat.totient\_mul}, \texttt{Nat.totient\_prime},
\texttt{Nat.totient\_prime\_pow}).

\begin{proposition}[Coprime multiplicativity]\label{prop:mul}
If $\gcd(a,b)=1$ then $\varphi(ab)=\varphi(a)\varphi(b)$.
\end{proposition}
\begin{proposition}[Primes]\label{prop:prime}
For prime $p$, $\varphi(p)=p-1$.
\end{proposition}
\begin{proposition}[Prime powers]\label{prop:pp}
For prime $p$ and $k\ge 1$, $\varphi(p^k)=p^{k-1}(p-1)$.
\end{proposition}
\begin{proposition}[Evenness, \texttt{Nat.totient\_even}]\label{prop:even}
For $m\ge 3$, $\varphi(m)$ is even.
\end{proposition}

\section{Explicit, multiplicatively-certified witnesses}\label{sec:witnesses}

Call $n$ a \emph{unit-shift collision} (or GHP witness) if
$\varphi(n)=\varphi(n+1)$. The next theorems certify witnesses structurally: factor
$n$ and $n+1$ into coprime prime powers, expand $\varphi$ via
Propositions~\ref{prop:mul}--\ref{prop:pp}, then verify the numerical identity.

\begin{theorem}[\texttt{ghp\_15}]\label{thm:15}
$\varphi(15)=\varphi(16)$.
\end{theorem}
\begin{proof}
$15=3\cdot5$, so $\varphi(15)=2\cdot4=8$; $16=2^4$, so $\varphi(16)=2^3=8$.
\end{proof}

\begin{theorem}[\texttt{ghp\_104}]\label{thm:104}
$\varphi(104)=\varphi(105)$.
\end{theorem}
\begin{proof}
$104=2^3\cdot13$, $\varphi=4\cdot12=48$; $105=3\cdot5\cdot7$, $\varphi=2\cdot4\cdot6=48$.
\end{proof}

\begin{theorem}[\texttt{ghp\_164}]\label{thm:164}
$\varphi(164)=\varphi(165)$.
\end{theorem}
\begin{proof}
$164=2^2\cdot41$, $\varphi=2\cdot40=80$; $165=3\cdot5\cdot11$, $\varphi=2\cdot4\cdot10=80$.
\end{proof}

\begin{theorem}[\texttt{ghp\_194}]\label{thm:194}
$\varphi(194)=\varphi(195)$.
\end{theorem}
\begin{proof}
$194=2\cdot97$, $\varphi=96$; $195=3\cdot5\cdot13$, $\varphi=2\cdot4\cdot12=96$.
\end{proof}

\begin{theorem}[\texttt{ghp\_255}]\label{thm:255}
$\varphi(255)=\varphi(256)$.
\end{theorem}
\begin{proof}
$255=3\cdot5\cdot17$, $\varphi=2\cdot4\cdot16=128$; $256=2^8$, $\varphi=2^7=128$.
The primes $3,5,17$ are Fermat primes ($2+1,4+1,16+1$); this is the archetypal
Fermat-prime versus power-of-two balancing.
\end{proof}

\begin{theorem}[\texttt{ghp\_495}]\label{thm:495}
$\varphi(495)=\varphi(496)$.
\end{theorem}
\begin{proof}
$495=3^2\cdot5\cdot11$, $\varphi=6\cdot4\cdot10=240$; $496=2^4\cdot31$,
$\varphi=8\cdot30=240$.
\end{proof}

\begin{theorem}[\texttt{ghp\_584}]\label{thm:584}
$\varphi(584)=\varphi(585)$.
\end{theorem}
\begin{proof}
$584=2^3\cdot73$, $\varphi=4\cdot72=288$; $585=3^2\cdot5\cdot13$,
$\varphi=6\cdot4\cdot12=288$.
\end{proof}

\begin{theorem}[\texttt{ghp\_975}]\label{thm:975}
$\varphi(975)=\varphi(976)$.
\end{theorem}
\begin{proof}
$975=3\cdot5^2\cdot13$, $\varphi=2\cdot20\cdot12=480$; $976=2^4\cdot61$,
$\varphi=8\cdot60=480$.
\end{proof}

\begin{remark}[The balancing principle]\label{rem:balance}
In each witness, one neighbor carries its $2$-adic mass as an explicit power of
two while the other is, up to a small odd core, a product of odd primes $p$ whose
$p-1$ are $2$-rich. The totient turns those $p-1$ factors into powers of two,
matching the opposite side. Theorem~\ref{thm:255} is purest:
$\varphi(3\cdot5\cdot17)=2\cdot4\cdot16=2^7=\varphi(2^8)$. This local mechanism is
what the GHP lower-bound family scales up.
\end{remark}

\section{The counting function and the transfer theorem}\label{sec:count}

\begin{definition}[\texttt{S1phi}]\label{def:S}
For $x\in\mathbb{N}$,
\[ \Sphi(x) := \#\{\, n : 1\le n\le x,\ \varphi(n)=\varphi(n+1)\,\}
            = \#\big(\{1,\dots,x\}\cap \W\big), \]
where $\W=\{n:\varphi(n)=\varphi(n+1)\}$ is the witness set: the cardinality of the
filter of $\{1,\dots,x\}$ by the decidable predicate $\varphi(n)=\varphi(n+1)$.
\end{definition}

\begin{proposition}[Monotonicity]\label{prop:mono}
If $x\le y$ then $\Sphi(x)\le \Sphi(y)$.
\end{proposition}
\begin{proof}
The filtered set for $x$ is a subset of that for $y$; apply monotonicity of
cardinality under inclusion (\texttt{Finset.card\_le\_card}).
\end{proof}

\begin{theorem}[Counting transfer, \texttt{S1phi\_ge\_card}]\label{thm:transfer}
Let $W\subseteq\{1,\dots,x\}$ be finite with $\varphi(w)=\varphi(w+1)$ for every
$w\in W$. Then $\#W \le \Sphi(x)$.
\end{theorem}
\begin{proof}
Each $w\in W$ satisfies the defining predicate and lies in $\{1,\dots,x\}$, so $W$
is a subset of the filtered interval of cardinality $\Sphi(x)$; conclude by
\texttt{Finset.card\_le\_card}.
\end{proof}

Theorem~\ref{thm:transfer} is the formal crux: it converts the constructive
content of the GHP lower bound into a quantitative statement about $\Sphi(x)$ with
no analysis at the transfer step.

\begin{corollary}[Explicit lower bounds]\label{cor:lb}
With the witnesses of Section~\ref{sec:witnesses} and the small solutions $1$
($\varphi(1)=\varphi(2)=1$) and $3$ ($\varphi(3)=\varphi(4)=2$),
\[ 6 \le \Sphi(194), \qquad 10 \le \Sphi(975). \]
\end{corollary}
\begin{proof}
Apply Theorem~\ref{thm:transfer} with $W=\{1,3,15,104,164,194\}$ and with
$W=\{1,3,15,104,164,194,255,495,584,975\}$.
\end{proof}

A direct search shows these are exact: $\Sphi(194)=6$ and $\Sphi(975)=10$, and the
full list of collisions up to $1000$ is $\{1,3,15,104,164,194,255,495,584,975\}$,
so $\Sphi(1000)=10$.

\section{Structural constraints}\label{sec:struct}

\begin{theorem}[Non-saturation, \texttt{S1phi\_lt\_self}]\label{thm:nonsat}
For every $x\ge 2$, $\Sphi(x) < x$.
\end{theorem}
\begin{proof}
Exhibit one certified non-collision in $\{1,\dots,x\}$: take $n=2$, where
$\varphi(2)=1\ne 2=\varphi(3)$. Hence the filtered interval is a proper subset of
$\{1,\dots,x\}$, and a proper subset of a finite set has strictly smaller
cardinality (\texttt{Finset.card\_lt\_card}).
\end{proof}

\begin{theorem}[Parity of collision values, \texttt{totient\_shift\_value\_even}]\label{thm:parity}
If $n\ge 3$ and $\varphi(n)=\varphi(n+1)$, then $\varphi(n)$ is even.
\end{theorem}
\begin{proof}
Since $n\ge 3$, Proposition~\ref{prop:even} gives $2\mid\varphi(n)$; the hypothesis
transfers evenness to $\varphi(n+1)$ as well.
\end{proof}

Theorem~\ref{thm:parity} is the crudest layer of a conjectural concentration
phenomenon: collision values should be multiplicatively rich, since two distinct
coprime factorizations yield the same totient only when that value admits enough
internal structure to be assembled two ways.

\section{Discussion}

The arc \eqref{eq:upper}--\eqref{eq:lower} is analytic, but \eqref{eq:lower} is
morally a count over a constructed family $\mathcal{F}_x \subseteq
\W\cap\{1,\dots,x\}$ generalizing Theorem~\ref{thm:255}: one builds a neighbor as a
power of two times a small core, and the opposite neighbor as a product of odd
primes $p$ with $p-1$ supported on small primes, arranged so the totients
coincide. The number of admissible balanced factorizations below $x$ is a
partition-type count whose logarithm is $\asymp\sqrt{\log x\,\log_2 x}$.
Theorem~\ref{thm:transfer} gives $\#\mathcal{F}_x \le \Sphi(x)$, so the
construction's size \emph{is} the lower bound. This is the bridge the paper names:
an analytic density theorem reduced, at its constructive heart, to verifiable
multiplicative identities and a one-line counting lemma.

\section{Future work}

\begin{itemize}
\item \textbf{Infinitude (open).} Prove $\Sphi(x)\to\infty$.
Theorem~\ref{thm:transfer} reduces this to exhibiting one infinite verifiable
family of balanced coprime factorizations.
\item \textbf{Intermediate growth.} Establish $(\log x)^A \le \Sphi(x) \le
x^{\varepsilon}$, matching the $\exp\{\pm(\tfrac12+o(1))\sqrt{\log x\,\log_2 x}\}$
shape; Theorems~\ref{thm:nonsat} and Corollary~\ref{cor:lb} pin the function
between trivial bounds.
\item \textbf{Value concentration.} Strengthen Theorem~\ref{thm:parity} from
parity to high divisibility.
\item \textbf{Smooth-number bridge.} Make precise the link between witness density
and smooth-number density underlying the shared exponent.
\end{itemize}

\section{Conclusion}

We isolated and machine-verified the constructive skeleton beneath the tightness
of the GHP unit-shift bound: eight structurally certified witnesses, a counting
transfer theorem, explicit bounds $6\le\Sphi(194)$ and $10\le\Sphi(975)$,
non-saturation $\Sphi(x)<x$, and the parity law. The recurring mechanism --- a
power of two balanced against a product of small odd primes via coprime
multiplicativity --- is the local engine that, scaled to an infinite family,
yields the matching lower bound \eqref{eq:lower}. The asymptotic tail remains
analytic; its constructive core is now verified.

